import{_ as l,a8 as e,o as n,c as i,ah as d,K as a}from"./chunks/framework.BUAh2RRO.js";import"./chunks/theme.-p-ond56.js";const P=JSON.parse('{"title":"性能优化之首屏加载","description":"","frontmatter":{"title":"性能优化之首屏加载","abstract":"首屏加载性能优化，涵盖 FCP、LCP 等核心指标，以及资源瘦身、网络优化、渲染优化三大类策略。","created":"2026-07-10T00:00:00.000Z","tags":["Web","性能优化"],"type":"概念解释","category":["🛠️ 工程工具","Frontend"]},"headers":[],"relativePath":"vault/Knowledge/Engineering/性能优化之首屏加载.md","filePath":"vault/Knowledge/Engineering/性能优化之首屏加载.md","lastUpdated":1790655645000}'),s={name:"vault/Knowledge/Engineering/性能优化之首屏加载.md"};function h(c,t,_,g,b,p){const r=e("NolebaseGitContributors"),o=e("NolebaseGitChangelog");return n(),i("div",null,[t[0]||(t[0]=d('<h1 id="性能优化之首屏加载" tabindex="-1">性能优化之首屏加载 <a class="header-anchor" href="#性能优化之首屏加载" aria-label="Permalink to “性能优化之首屏加载”">​</a></h1><p>首屏加载（FCP/LCP）直接影响用户体验和 SEO，优化目标是使用户可见的核心内容尽快呈现。</p><h2 id="核心指标" tabindex="-1">核心指标 <a class="header-anchor" href="#核心指标" aria-label="Permalink to “核心指标”">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th>目标</th></tr></thead><tbody><tr><td>FCP</td><td>首次内容渲染</td><td>&lt; 1.8s</td></tr><tr><td>LCP</td><td>最大内容绘制</td><td>&lt; 2.5s</td></tr><tr><td>TTI</td><td>可交互时间</td><td>&lt; 3.8s</td></tr></tbody></table><h2 id="优化策略" tabindex="-1">优化策略 <a class="header-anchor" href="#优化策略" aria-label="Permalink to “优化策略”">​</a></h2><h3 id="_1-资源瘦身" tabindex="-1">1. 资源瘦身 <a class="header-anchor" href="#_1-资源瘦身" aria-label="Permalink to “1. 资源瘦身”">​</a></h3><ul><li><strong>代码分割</strong>：按路由/组件拆分，只加载首屏需要的 JS（React.lazy / dynamic import）</li><li><strong>Tree Shaking</strong>：移除未使用的模块导出</li><li><strong>图片优化</strong>：WebP/AVIF 格式、响应式图片（srcset）、懒加载</li></ul><h3 id="_2-网络优化" tabindex="-1">2. 网络优化 <a class="header-anchor" href="#_2-网络优化" aria-label="Permalink to “2. 网络优化”">​</a></h3><ul><li><strong>HTTP/2 多路复用</strong> + 服务端推送</li><li><strong>CDN 分发</strong>静态资源</li><li><strong>关键 CSS 内联</strong>，其余异步加载</li><li><strong>资源预加载</strong>：<code>&lt;link rel=&quot;preload&quot;&gt;</code>、<code>&lt;link rel=&quot;prefetch&quot;&gt;</code></li></ul><h3 id="_3-渲染优化" tabindex="-1">3. 渲染优化 <a class="header-anchor" href="#_3-渲染优化" aria-label="Permalink to “3. 渲染优化”">​</a></h3><ul><li><strong>SSR / SSG</strong>：服务端渲染直出 HTML，减少客户端 JS 渲染耗时</li><li><strong>骨架屏</strong>：加载中占位，减少 CLS</li><li><strong>避免 JS 阻塞渲染</strong>：脚本加 <code>async</code>/<code>defer</code></li></ul><h3 id="_4-缓存策略" tabindex="-1">4. 缓存策略 <a class="header-anchor" href="#_4-缓存策略" aria-label="Permalink to “4. 缓存策略”">​</a></h3><p>强缓存（Cache-Control） + 协商缓存（ETag） + Service Worker。</p>',13)),a(r),a(o)])}const C=l(s,[["render",h]]);export{P as __pageData,C as default};
